const merged = $input.first().json;
const input = { ...merged, crawl4aiResult: merged };

let sources = [];
try {
  sources = typeof input.sourcesJson === 'string' ? JSON.parse(input.sourcesJson || '[]') : (input.sourcesJson || []);
} catch (error) {
  throw new Error('sourcesJson is not valid JSON. Fix the Set Config Here node first.');
}

if (!Array.isArray(sources) || !sources.length) {
  throw new Error('Add at least one Kijiji list_url in the Set Config Here node.');
}

const normalizeCrawlItems = (value) => {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap(normalizeCrawlItems);
  if (Array.isArray(value.results)) return value.results;
  if (Array.isArray(value.data)) return value.data;
  if (value.body) return normalizeCrawlItems(value.body);
  return [value];
};

const decodeHtml = (value = '') => String(value || '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#34;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>');

const cleanText = (value = '') => decodeHtml(String(value || ''))
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const normalizeUrl = (value = '') => {
  const raw = String(value || '').trim();
  if (!raw) return '';
  try {
    const url = new URL(raw, 'https://www.kijiji.ca');
    url.hash = '';
    return url.toString().replace(/\/$/, '');
  } catch {
    return raw.replace(/#.*$/, '').replace(/\/$/, '');
  }
};

const slugToWords = (value = '') => String(value || '')
  .replace(/^city-of-/i, '')
  .replace(/^ville-de-/i, '')
  .replace(/-/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .replace(/\b\w/g, (m) => m.toUpperCase());

const inferCityFromUrl = (url = '') => {
  const match = String(url || '').match(/\/((?:city|region)-of-[^/]+|city-of-[^/]+|ville-de-[^/]+)\//i);
  return slugToWords(match?.[1] || '');
};

const inferCountryFromUrl = (url = '') => /kijiji\.ca/i.test(url) ? 'Canada' : '';

const normalizeCondition = (value = '') => {
  const text = String(value || '').toLowerCase();
  if (!text) return '';
  if (/used - like new|usedlikenew|like new/.test(text)) return 'like_new';
  if (/used - good|usedgood|good/.test(text)) return 'good';
  if (/used - fair|usedfair|fair/.test(text)) return 'fair';
  if (/used - poor|usedpoor|poor/.test(text)) return 'poor';
  if (/new/.test(text)) return 'new';
  if (/used/.test(text)) return 'used';
  return '';
};

const extractJsonScriptBlocks = (html = '') => {
  const matches = [...String(html || '').matchAll(/<script[^>]*type=["']application\/(?:ld\+json|json)["'][^>]*>([\s\S]*?)<\/script>/gi)];
  return matches.map((match) => match[1]).filter(Boolean);
};

const extractNextData = (html = '') => {
  const blocks = extractJsonScriptBlocks(html);
  for (const block of blocks) {
    const text = String(block || '').trim();
    if (!text.startsWith('{')) continue;
    try {
      const parsed = JSON.parse(text);
      if (parsed?.props?.pageProps?.__APOLLO_STATE__ || parsed?.props?.pageProps?.apolloState) return parsed;
    } catch {}
  }
  return null;
};

const extractItemListJsonLd = (html = '') => {
  const blocks = extractJsonScriptBlocks(html);
  for (const block of blocks) {
    const text = String(block || '').trim();
    if (!text.startsWith('{') && !text.startsWith('[')) continue;
    try {
      const parsed = JSON.parse(text);
      const candidates = Array.isArray(parsed) ? parsed : [parsed];
      for (const item of candidates) {
        if (item?.['@type'] === 'ItemList' && Array.isArray(item?.itemListElement)) return item;
      }
    } catch {}
  }
  return null;
};

const priceTextFromListing = (listing = {}) => {
  const amount = Number(listing?.price?.amount);
  const currency = String(listing?.price?.currency || 'CAD').trim();
  if (Number.isFinite(amount)) {
    const major = amount >= 1000 ? (amount / 100).toFixed(2) : String(amount);
    return currency === 'CAD' ? '$' + major : currency + ' ' + major;
  }
  return '';
};

const extractApolloListings = (nextData) => {
  const apollo = nextData?.props?.pageProps?.__APOLLO_STATE__ || nextData?.props?.pageProps?.apolloState || {};
  return Object.values(apollo)
    .filter((entry) => entry && entry.__typename === 'StandardListing' && entry.url)
    .map((entry) => {
      const attrs = Array.isArray(entry?.attributes?.all) ? entry.attributes.all : [];
      const attrMap = new Map(attrs.map((item) => [String(item?.canonicalName || '').trim(), item]));
      const conditionAttr = attrMap.get('condition');
      const sellerTypeAttr = attrMap.get('forsaleby');
      return {
        listingId: String(entry.id || '').trim(),
        title: cleanText(entry.title || ''),
        description: cleanText(entry.description || ''),
        sourceUrl: normalizeUrl(entry.url || ''),
        imageUrls: Array.isArray(entry.imageUrls) ? entry.imageUrls.map((url) => normalizeUrl(url)).filter(Boolean) : [],
        imageUrl: Array.isArray(entry.imageUrls) && entry.imageUrls[0] ? normalizeUrl(entry.imageUrls[0]) : '',
        priceValue: Number.isFinite(Number(entry?.price?.amount)) ? String(entry.price.amount) : '',
        currency: String(entry?.price?.currency || 'CAD').trim() || 'CAD',
        priceText: priceTextFromListing(entry),
        city: cleanText(entry?.location?.name || ''),
        locationAddress: cleanText(entry?.location?.address || ''),
        latitude: entry?.location?.coordinates?.latitude ?? null,
        longitude: entry?.location?.coordinates?.longitude ?? null,
        sellerId: String(entry?.posterInfo?.posterId || '').trim(),
        sellerType: cleanText((sellerTypeAttr?.values || sellerTypeAttr?.canonicalValues || [])[0] || entry?.posterInfo?.sellerType || ''),
        condition: normalizeCondition((conditionAttr?.values || conditionAttr?.canonicalValues || [])[0] || ''),
        postedAt: String(entry.activationDate || entry.sortingDate || '').trim(),
        sortingDate: String(entry.sortingDate || '').trim(),
        views: Number.isFinite(Number(entry?.metrics?.views)) ? Number(entry.metrics.views) : null
      };
    });
};

const extractJsonLdListings = (itemList) => {
  const items = Array.isArray(itemList?.itemListElement) ? itemList.itemListElement : [];
  return items.map((entry) => {
    const item = entry?.item || entry || {};
    return {
      listingId: String(item?.url || '').match(/\/(\d+)(?:[/?#]|$)/)?.[1] || '',
      title: cleanText(item?.name || ''),
      description: cleanText(item?.description || ''),
      sourceUrl: normalizeUrl(item?.url || ''),
      imageUrls: item?.image ? [normalizeUrl(Array.isArray(item.image) ? item.image[0] : item.image)] : [],
      imageUrl: item?.image ? normalizeUrl(Array.isArray(item.image) ? item.image[0] : item.image) : '',
      priceValue: String(item?.offers?.price || '').trim(),
      currency: String(item?.offers?.priceCurrency || 'CAD').trim() || 'CAD',
      priceText: item?.offers?.price ? ('$' + item.offers.price) : '',
      city: '',
      locationAddress: '',
      latitude: null,
      longitude: null,
      sellerId: '',
      sellerType: '',
      condition: '',
      postedAt: '',
      sortingDate: '',
      views: null
    };
  }).filter((row) => row.title && row.sourceUrl);
};

const extractKijijiLinkListings = (html = '') => {
  const input = String(html || '');
  const seen = new Set();
  const rows = [];
  const linkPattern = /<a\b[^>]+href=["']([^"']*\/v-[^"']+\/[^"']+\/\d+[^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let match;
  while ((match = linkPattern.exec(input))) {
    const sourceUrl = normalizeUrl(match[1]);
    if (!sourceUrl || seen.has(sourceUrl)) continue;
    seen.add(sourceUrl);
    const aroundStart = Math.max(0, match.index - 1800);
    const aroundEnd = Math.min(input.length, linkPattern.lastIndex + 2200);
    const block = input.slice(aroundStart, aroundEnd);
    const linkText = cleanText(match[2]);
    const title = cleanText(linkText || block.match(/<(?:h2|h3)[^>]*>([\s\S]*?)<\/(?:h2|h3)>/i)?.[1] || block.match(/title=["']([^"']+)["']/i)?.[1] || '');
    if (!title || /^view details$/i.test(title)) continue;
    const priceMatch = block.match(/(?:\$|CAD\s*)\s?\d[\d,.]*(?:\.\d{2})?|Please Contact|Free/iu);
    const imageMatch = block.match(/<img[^>]+(?:src|data-src|srcset)=["']([^"',\s]+)[^"']*["']/i);
    const locationMatch = block.match(/(?:location|address)[^>]{0,80}>([\s\S]{0,120}?)<\//i);
    const dateMatch = block.match(/\b(?:just now|today|yesterday|\d+\s+(?:minute|minutes|hour|hours|day|days|week|weeks)\s+ago|[A-Z][a-z]{2}\s+\d{1,2})\b/i);
    rows.push({
      listingId: sourceUrl.match(/\/(\d+)(?:[/?#]|$)/)?.[1] || '',
      title,
      description: cleanText(block).slice(0, 500),
      sourceUrl,
      imageUrls: imageMatch?.[1] ? [normalizeUrl(imageMatch[1])] : [],
      imageUrl: imageMatch?.[1] ? normalizeUrl(imageMatch[1]) : '',
      priceValue: priceMatch?.[0] ? String(priceMatch[0]).replace(/[^0-9.]/g, '') : '',
      currency: 'CAD',
      priceText: cleanText(priceMatch?.[0] || ''),
      city: cleanText(locationMatch?.[1] || ''),
      locationAddress: cleanText(locationMatch?.[1] || ''),
      latitude: null,
      longitude: null,
      sellerId: '',
      sellerType: '',
      condition: normalizeCondition(block),
      postedAt: cleanText(dateMatch?.[0] || ''),
      sortingDate: '',
      views: null
    });
  }
  return rows;
};

const matchesCity = (listing, source) => {
  const strict = source.strict_city_match === true || String(source.strict_city_match || '').toLowerCase() === 'true';
  if (!strict) return true;
  const target = cleanText(source.city || inferCityFromUrl(source.list_url || '')).toLowerCase();
  if (!target) return true;
  const hay = [listing.city, listing.locationAddress, source.name].map((v) => cleanText(v).toLowerCase()).join(' ');
  return hay.includes(target);
};

const crawlItems = normalizeCrawlItems(input.crawl4aiResult || input);
const crawlByUrl = new Map();
for (const item of crawlItems) {
  const key = normalizeUrl(item.url || item.redirected_url || '');
  if (key) crawlByUrl.set(key, item);
}

const output = [];
for (const source of sources.filter((entry) => entry && entry.enabled !== false)) {
  const listUrl = normalizeUrl(source.list_url || source.url || '');
  if (!listUrl) {
    output.push({ json: { recordType: 'kijiji_source', sourceName: source.name || 'Unnamed source', crawlStatus: 'failed', error: 'Missing list_url in sourcesJson.' } });
    continue;
  }

  const crawlItem = crawlByUrl.get(listUrl) || Array.from(crawlByUrl.values()).find((entry) => normalizeUrl(entry.url || entry.redirected_url || '') === listUrl);
  if (!crawlItem) {
    output.push({ json: { recordType: 'kijiji_source', sourceName: source.name || listUrl, listUrl, crawlStatus: 'failed', error: 'Crawl4AI did not return a result for this list_url.' } });
    continue;
  }

  const raw = crawlItem.html || crawlItem.cleaned_html || crawlItem.fit_html || crawlItem.markdown?.raw_markdown || crawlItem.markdown || crawlItem.fit_markdown || '';
  if (!raw) {
    output.push({ json: { recordType: 'kijiji_source', sourceName: source.name || listUrl, listUrl, crawlStatus: 'failed', error: crawlItem.error_message || 'Crawl4AI did not return HTML/markdown for this source.' } });
    continue;
  }

  const nextData = extractNextData(raw);
  let listings = nextData ? extractApolloListings(nextData) : [];
  if (!listings.length) {
    const itemList = extractItemListJsonLd(raw);
    listings = itemList ? extractJsonLdListings(itemList) : [];
  }
  if (!listings.length) {
    listings = extractKijijiLinkListings(raw);
  }

  const maxListings = Math.max(1, Number(source.max_listings || 25));
  const cityFallback = cleanText(source.city || inferCityFromUrl(listUrl));
  const countryFallback = cleanText(source.country || inferCountryFromUrl(listUrl));
  const dedupe = new Set();
  const normalized = listings
    .filter((listing) => listing && listing.sourceUrl && !dedupe.has(listing.sourceUrl) && (dedupe.add(listing.sourceUrl) || true))
    .map((listing, index) => ({
      recordType: 'kijiji_listing',
      sourceName: source.name || cityFallback || 'Kijiji Source',
      listUrl,
      rank: index + 1,
      listingId: listing.listingId,
      title: listing.title,
      description: listing.description,
      priceText: listing.priceText,
      priceValue: listing.priceValue,
      currency: listing.currency || 'CAD',
      city: listing.city || cityFallback,
      country: countryFallback,
      locationAddress: listing.locationAddress || '',
      latitude: listing.latitude,
      longitude: listing.longitude,
      imageUrl: listing.imageUrl,
      imageUrls: Array.isArray(listing.imageUrls) ? listing.imageUrls.join('|') : '',
      sourceUrl: listing.sourceUrl,
      sourceSite: 'Kijiji',
      sellerId: listing.sellerId || '',
      sellerType: listing.sellerType || '',
      condition: listing.condition || '',
      postedAt: listing.postedAt || '',
      sortingDate: listing.sortingDate || '',
      views: listing.views,
      appCategory: source.app_category || '',
      appSubcategory: source.app_subcategory || ''
    }))
    .filter((listing) => matchesCity(listing, source))
    .slice(0, maxListings);

  output.push({
    json: {
      recordType: 'kijiji_source',
      sourceName: source.name || cityFallback || listUrl,
      listUrl,
      crawlStatus: normalized.length ? 'success' : 'empty',
      city: cityFallback,
      country: countryFallback,
      listingCount: normalized.length,
      note: normalized.length ? '' : 'No listings were extracted. Check whether Crawl4AI returned Kijiji listing HTML or a consent/blocked/empty page.'
    }
  });

  normalized.forEach((listing) => output.push({ json: listing }));
}

return output.length ? output : [{ json: { recordType: 'kijiji_source', crawlStatus: 'failed', error: 'Workflow completed but produced no output.' } }];
